import json

test = [
    [5, 8, 7, 8, 5, 5],
    [8, 8, 7, 4, 8, 8],
    [5, 4, 8, 4, 8, 5],
    [8, 7, 8, 8, 8, 8],
    [8, 8, 8, 8, 5, 5],
    [8, 5, 5, 8, 5, 5]
]

def transform(grid):
    n = len(grid)
    out = [[0]*(2*n) for _ in range(2*n)]
    for i in range(n):
        for j in range(n):
            out[i][j] = grid[i][j]
    for j in range(n):
        for c in range(n):
            out[j][n+c] = grid[n-1-c][j]
    for r in range(n):
        for j in range(n):
            out[n+r][j] = grid[j][n-1-r]
    for r in range(n):
        for c in range(n):
            out[n+r][n+c] = grid[n-1-r][n-1-c]
    return out

final_result = transform(test)
print(json.dumps(final_result))
